public class InnerAutoMLJobTimeSeriesForecastingJobConfigFactory(Action<Humidifier.SageMaker.AutoMLJobTypes.TimeSeriesForecastingJobConfig> factoryAction = null) : SubResourceFactory<Humidifier.SageMaker.AutoMLJobTypes.TimeSeriesForecastingJobConfig>
{

    internal InnerAutoMLJobCandidateGenerationConfigFactory CandidateGenerationConfigFactory { get; set; }

    internal InnerAutoMLJobAutoMLJobCompletionCriteriaFactory CompletionCriteriaFactory { get; set; }

    internal InnerAutoMLJobTimeSeriesTransformationsFactory TransformationsFactory { get; set; }

    internal InnerAutoMLJobTimeSeriesConfigFactory TimeSeriesConfigFactory { get; set; }

    protected override Humidifier.SageMaker.AutoMLJobTypes.TimeSeriesForecastingJobConfig Create()
    {
        var timeSeriesForecastingJobConfigResult = CreateTimeSeriesForecastingJobConfig();
        factoryAction?.Invoke(timeSeriesForecastingJobConfigResult);

        return timeSeriesForecastingJobConfigResult;
    }

    private Humidifier.SageMaker.AutoMLJobTypes.TimeSeriesForecastingJobConfig CreateTimeSeriesForecastingJobConfig()
    {
        var timeSeriesForecastingJobConfigResult = new Humidifier.SageMaker.AutoMLJobTypes.TimeSeriesForecastingJobConfig();

        return timeSeriesForecastingJobConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AutoMLJobTypes.TimeSeriesForecastingJobConfig result)
    {
        base.CreateChildren(result);

        result.CandidateGenerationConfig ??= CandidateGenerationConfigFactory?.Build();
        result.CompletionCriteria ??= CompletionCriteriaFactory?.Build();
        result.Transformations ??= TransformationsFactory?.Build();
        result.TimeSeriesConfig ??= TimeSeriesConfigFactory?.Build();
    }

} // End Of Class

